async function parseList(html, context) {
  var ctx = context || {};
  var page = ctx.page || 1;
  var keyword = ctx.keyword || '';
  var baseUrl = (ctx.baseUrl || 'https://m.baozimh.one').replace(/\/$/, '');
  var targetUrl = page == 1
    ? baseUrl + '/s?q=' + encodeURIComponent(keyword)
    : baseUrl + '/s/' + encodeURIComponent(keyword) + '?page=' + page;
  var listHtml = await ctx.http.get(targetUrl);
  if (typeof listHtml !== 'string') listHtml = '';
  var results = [];
  var re = /<a\s+([^>]*)href="(\/manga\/[^"]+)"([^>]*)>([\s\S]*?)<\/a>/gi;
  var match;
  while ((match = re.exec(listHtml)) !== null) {
    var block = match[4];
    if (!/<img/i.test(block)) continue;
    var href = match[2];
    var id = href;
    var titleMatch = block.match(/<h3[^>]*>([\s\S]*?)<\/h3>/i);
    var title = titleMatch ? titleMatch[1].replace(/<[^>]+>/g, '').trim() : '';
    var cover = '';
    var imgSrcMatch = block.match(/<img[^>]+src="([^"]+)"[^>]*>/i);
    if (imgSrcMatch) cover = imgSrcMatch[1];
    if (!cover) {
      var dataSrcMatch = block.match(/<img[^>]+data-src="([^"]+)"[^>]*>/i);
      if (dataSrcMatch) cover = dataSrcMatch[1];
    }
    if (!cover) {
      var dataOriginalMatch = block.match(/<img[^>]+data-original="([^"]+)"[^>]*>/i);
      if (dataOriginalMatch) cover = dataOriginalMatch[1];
    }
    if (!title || !id) continue;
    if (cover && cover.startsWith('/')) cover = baseUrl + cover;
    results.push({
      id: id,
      title: title,
      cover: cover,
      detailUrl: baseUrl + href
    });
  }
  return results;
}

