detail.script:
async function parseDetail(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://m.baozimh.one').replace(/\/$/, '');
  var url = ctx.url || '';
  if (!html && url) {
    try { html = await ctx.http.get(url); } catch (e) { html = ''; }
  }
  if (typeof html !== 'string') html = '';
  var stripTags = function(s) { return s.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim(); };
  var title = '';
  var titleMatch = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  if (titleMatch) title = stripTags(titleMatch[1]);
  var cover = '';
  var coverMatch = html.match(/<img[^>]+id=["']MangaCard["'][^>]*(?:src|data-src)=["']([^"']+)["']/i);
  if (!coverMatch) coverMatch = html.match(/<img[^>]+(?:src|data-src)=["']([^"']+)["'][^>]*id=["']MangaCard["']/i);
  if (!coverMatch) {
    var cardMatch = html.match(/<div[^>]+id=["']MangaCard["'][^>]*>([\s\S]*?)<\/div>/i);
    if (cardMatch) {
      var imgMatch = cardMatch[1].match(/<img[^>]+(?:src|data-src)=["']([^"']+)["']/i);
      if (imgMatch) cover = imgMatch[1];
    }
  }
  if (coverMatch) cover = coverMatch[1];
  if (cover && cover.startsWith('/')) cover = baseUrl + cover;
  var description = '';
  var descMatch = html.match(/<p[^>]+class=["'][^"']*line-clamp-4[^"']*["'][^>]*>([\s\S]*?)<\/p>/i);
  if (!descMatch) descMatch = html.match(/<p[^>]+class=["'][^"']*text-sm[^"']*text-foreground[^"']*["'][^>]*>([\s\S]*?)<\/p>/i);
  if (!descMatch) {
    var firstP = html.match(/<p[^>]*>([\s\S]*?)<\/p>/i);
    if (firstP) description = stripTags(firstP[1]);
  }
  if (descMatch) description = stripTags(descMatch[1]);
  var author = '';
  var authorMatch = html.match(/<a[^>]+href=["']\/manga-author\/[^>]*>([\s\S]*?)<\/a>/i);
  if (authorMatch) author = stripTags(authorMatch[1]);
  var authorSlug = '';
  var authorSlugMatch = html.match(/<a[^>]+href=["']\/manga-author\/([^"'\s\/]+)["']/i);
  if (authorSlugMatch) authorSlug = authorSlugMatch[1];
  var authorUrl = '';
  if (authorSlug) authorUrl = baseUrl + '/manga-author/' + authorSlug;
  var genre = '';
  var genreMatch = html.match(/<a[^>]+href=["']\/manga-genre\/[^>]*>([\s\S]*?)<\/a>/i);
  if (genreMatch) genre = stripTags(genreMatch[1]);
  var tags = [];
  var tagUrls = [];
  var tagRe = /<a[^>]+href=["'](\/manga-genre\/[^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  var tm;
  while ((tm = tagRe.exec(html)) !== null) {
    var tHref = tm[1];
    if (tHref.indexOf('/') === 0) tHref = baseUrl + tHref;
    var t = stripTags(tm[2]);
    if (t && tags.indexOf(t) === -1) { tags.push(t); tagUrls.push(tHref); }
  }
  var tagRe2 = /<a[^>]+href=["'](\/manga-tag\/[^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  while ((tm = tagRe2.exec(html)) !== null) {
    var t2Href = tm[1];
    if (t2Href.indexOf('/') === 0) t2Href = baseUrl + t2Href;
    var t2 = stripTags(tm[2]);
    if (t2 && tags.indexOf(t2) === -1) { tags.push(t2); tagUrls.push(t2Href); }
  }
  var status = '';
  var statusMatch = html.match(/(?:狀態|状态|連載狀態|连载状态)\s*[：:]\s*(?:<[^>]+>\s*)*(連載中|已完結|連載|完結|连载中|已完结|连载|完结)/i);
  if (statusMatch) {
    status = statusMatch[2];
  } else {
    var statusFallback = html.match(/<(?:span|dd|p|a|li)[^>]*>\s*(連載中|已完結|连载中|已完结)\s*<\//i);
    if (statusFallback) status = statusFallback[1];
  }
  var recommendations = [];
  var recSectionMatch = html.match(/<(?:section|div)[^>]*(?:class|id|data-[\w-]+)=["'][^"']*(?:related|recommend|推薦|推荐|相關|相关)[^"']*["'][^>]*>([\s\S]*?)<\/(?:section|div)>/i);
  if (recSectionMatch) {
    var recHtml = recSectionMatch[1];
    var recRe = /<a\s+([^>]*)href=["'](\/manga\/[^"']+)["']([^>]*)>([\s\S]*?)<\/a>/gi;
    var rm;
    while ((rm = recRe.exec(recHtml)) !== null) {
      var recBlock = rm[4];
      if (!/<img/i.test(recBlock)) continue;
      var recTitleMatch = recBlock.match(/<h3[^>]*>([\s\S]*?)<\/h3>/i);
      if (!recTitleMatch) recTitleMatch = recBlock.match(/<img[^>]+(?:alt|title)=["']([^"']+)["']/i);
      var recTitle = recTitleMatch ? stripTags(recTitleMatch[1]) : '';
      var recCover = '';
      var recImgMatch = recBlock.match(/<img[^>]+src=["']([^"']+)["']/i);
      if (!recImgMatch) recImgMatch = recBlock.match(/<img[^>]+data-src=["']([^"']+)["']/i);
      if (!recImgMatch) recImgMatch = recBlock.match(/<img[^>]+data-original=["']([^"']+)["']/i);
      if (recImgMatch) recCover = recImgMatch[1];
      if (!recTitle) continue;
      if (recCover && recCover.startsWith('/')) recCover = baseUrl + recCover;
      recommendations.push({ title: recTitle, coverUrl: recCover });
    }
  }
  var mid = '';
  var midMatch = html.match(/data-mid=["'](\d+)["']/i);
  if (midMatch) mid = midMatch[1];
  return {
    title: title,
    coverUrl: cover,
    author: author,
    authorUrl: authorUrl,
    authorSlug: authorSlug,
    genre: genre,
    tags: tags,
    tagUrls: tagUrls,
    description: description,
    status: status,
    recommendations: recommendations,
    mid: mid
  };
}

chapters.script:
async function parseChapters(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://m.baozimh.one').replace(/\/$/, '');
  var mid = '';
  var midMatch = html.match(/data-mid=["'](\d+)["']/i);
  if (midMatch) mid = midMatch[1];
  if (!mid) {
    var mangaIdMatch = html.match(/id=["']mangachapters["'][^>]*data-mid=["'](\d+)["']/i);
    if (mangaIdMatch) mid = mangaIdMatch[1];
  }
  if (!mid) return [];
  var apiUrl = 'https://v2.apikk.top/api/manga/get?mid=' + mid + '&mode=all&t=' + Date.now();
  try {
    var resp = await ctx.http.getJson(apiUrl);
    var data = resp && resp.data;
    if (!data || !data.chapters) return [];
    var results = [];
    for (var i = 0; i < data.chapters.length; i++) {
      var ch = data.chapters[i];
      var cid = ch.id;
      var attrs = ch.attributes || {};
      var title = attrs.title ? attrs.title : '';
      var updatedAtRaw = '';
      if (attrs.updated_at) updatedAtRaw = attrs.updated_at;
      else if (attrs.updatedAt) updatedAtRaw = attrs.updatedAt;
      else if (ch.updated_at) updatedAtRaw = ch.updated_at;
      else if (ch.updatedAt) updatedAtRaw = ch.updatedAt;
      else if (ch.time) updatedAtRaw = ch.time;
      else if (ch.date) updatedAtRaw = ch.date;
      else if (ch.timestamp) updatedAtRaw = ch.timestamp;
      var updatedAt = '';
      if (updatedAtRaw) {
        if (typeof updatedAtRaw === 'number') {
          var ts = updatedAtRaw;
          if (ts < 1000000000000) ts = ts * 1000;
          updatedAt = new Date(ts).toISOString();
        } else {
          updatedAt = String(updatedAtRaw);
        }
      }
      results.push({
        id: mid + '@' + cid,
        title: title,
        url: baseUrl + '/manga/' + mid + '/' + cid,
        updatedAt: updatedAt
      });
    }
    return results;
  } catch (e) {
    return [];
  }
}

images.script:
function decodeImages(raw) {
    var prefix = 'J7r';
    var suffix = 'nQ';
    var marker = 'kD';
    var keyB = 'W4s';
    var chunkSize = 7;
    var src = '_-9876543210abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
    var dst = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
    if (!raw || typeof raw !== 'string' || raw.slice(0, prefix.length) !== prefix || raw.slice(-suffix.length) !== suffix) {
      return null;
    }
    var body = raw.slice(prefix.length, -suffix.length);
    var keyBLen = keyB.length;
    var markerLen = marker.length;
    var keyPos = body.indexOf(keyB);
    if (keyPos < 0) return null;
    // kD 在当前数据里可能出现在多处，逐个尝试，选能解出合法 JSON 的那个
    var kdPositions = [];
    var searchFrom = 0;
    while (true) {
      var p = body.indexOf(marker, searchFrom);
      if (p < 0 || p >= keyPos) break;
      kdPositions.push(p);
      searchFrom = p + markerLen;
    }
    var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
    for (var idx = 0; idx < kdPositions.length; idx++) {
      var kdPos = kdPositions[idx];
      var cLen = keyPos - kdPos - markerLen;
      if (cLen < 0) continue;
      var tail = body.substr(keyPos + keyBLen);
      var part1 = body.substr(0, kdPos);
      var part3 = body.substr(kdPos + markerLen, cLen);
      var combined = tail + part1 + part3;
      var buf = '';
      for (var i = 0; i < combined.length; i += chunkSize) {
        var chunk = combined.substr(i, chunkSize);
        if (((i / chunkSize) | 0) % 2 === 1) {
          chunk = chunk.split('').reverse().join('');
        }
        buf += chunk;
      }
      var mapped = '';
      for (var j = 0; j < buf.length; j++) {
        var ch = buf[j];
        var sidx = src.indexOf(ch);
        mapped += sidx >= 0 ? dst[sidx] : ch;
      }
      var b64 = mapped.replace(/-/g, '+').replace(/_/g, '/');
      var pad = (4 - b64.length % 4) % 4;
      for (var p2 = 0; p2 < pad; p2++) b64 += '=';
      try {
        var out = '';
        for (var k = 0; k < b64.length; k += 4) {
          var e1 = chars.indexOf(b64.charAt(k));
          var e2 = chars.indexOf(b64.charAt(k + 1));
          var e3 = chars.indexOf(b64.charAt(k + 2));
          var e4 = chars.indexOf(b64.charAt(k + 3));
          out += String.fromCharCode((e1 << 2) | (e2 >> 4));
          if (e3 !== 64) out += String.fromCharCode(((e2 & 15) << 4) | (e3 >> 2));
          if (e4 !== 64) out += String.fromCharCode(((e3 & 3) << 6) | e4);
        }
        try { out = decodeURIComponent(escape(out)); } catch (e2) {}
        var parsed = JSON.parse(out);
        if (parsed && Array.isArray(parsed) && parsed.length > 0 && parsed[0] && parsed[0].url) {
          return parsed;
        }
      } catch (e) {
        // 该 kdPos 不是真正的分隔符，继续尝试下一个候选
      }
    }
    return null;
  }


  function _extractImageUrls(dataObj) {
    if (!dataObj || !dataObj.info || !dataObj.info.images) return [];
    var raw = dataObj.info.images.images;
    var images = null;
    if (typeof raw === 'string') {
      images = decodeImages(raw);
    } else if (Array.isArray(raw)) {
      images = raw;
    }
    if (!Array.isArray(images)) return [];
    var cdn = 'https://t40-1-4.g-mh.online';
    return images.map(function(item) {
      var u = item.url;
      if (!u) return '';
      if (u.startsWith('/')) u = cdn + u;
      else if (!/^https?:\/\//.test(u)) u = cdn + '/' + u;
      return u;
    }).filter(function(u) { return u && u.length > 0; });
  }

  // 同步入口：flutter_js 真机无法 await 异步函数，因此这里只负责从注入的
  // context(mid/cid) 拼出 API 地址并返回 __meta 描述符，由 ScriptResolver
  // 在 Dart 侧用源的防盗链/UA 预取，再调用 __processImages 同步解码。
  function parseImages(html, context) {
    var ctx = context || {};
    var mid = ctx.mid || '';
    var cid = ctx.cid || '';
    // 兜底：id 可能以 "mid@cid" 形式传入
    if ((!mid || !cid) && ctx.id && typeof ctx.id === 'string' && ctx.id.indexOf('@') > 0) {
      var parts = ctx.id.split('@');
      if (!mid) mid = parts[0];
      if (!cid) cid = parts[1];
    }
    // 再兜底：从章节页 HTML 中正则提取 /manga/{mid}/{cid}
    if (!mid || !cid) {
      try {
        var m = (html + '').match(/\/manga\/(\d+)\/(\d+)/);
        if (m) { if (!mid) mid = m[1]; if (!cid) cid = m[2]; }
      } catch (e) {}
    }
    if (!mid || !cid) return [];
    var apiUrl = 'https://v2.apikk.top/api/v2/chapter/getinfo?m=' + mid + '&c=' + cid;
    return { __meta: true, __fetchUrl: apiUrl, __processor: '__processImages' };
  }

  // 处理器：接收 Dart 侧预取的完整 API 响应 { code, data:{ info:{ images:{ images } } } }
  function __processImages(apiJson, context) {
    var data = null;
    if (apiJson && apiJson.data) data = apiJson.data;
    else if (apiJson && apiJson.info) data = apiJson;
    return _extractImageUrls(data);
  }
